SELECT [t].[TimelineId], [t].[CreatedAt], [t].[Description], [t].[Name], [t].[UpdatedAt], [t].[UserId], [t1].[TimelineUserId], [t1].[Active], [t1].[CreatedAt], [t1].[Description], [t1].[Name], [t1].[TimelineId], [t1].[UpdatedAt], [t1].[UserId] FROM [Timelines] AS [t] LEFT JOIN [TimelineUsers] AS [t1] ON [t].[TimelineId] = [t1].[TimelineId] WHERE [t].[UserId] IN ( SELECT [c].[value] FROM OPENJSON(@__connectedUserIds_0) WITH ([value] int '$') AS [c] ) OR EXISTS ( SELECT 1 FROM [TimelineUsers] AS [t0] WHERE [t].[TimelineId] = [t0].[TimelineId] AND [t0].[UserId] IN ( SELECT [c0].[value] FROM OPENJSON(@__connectedUserIds_0) WITH ([value] int '$') AS [c0] )) ORDER BY [t].[TimelineId]